import { useEffect, useRef, useState, type ChangeEvent } from 'react';
import { Activity, Archive, ArrowLeft, AudioLines, Calculator, CalendarDays, Check, ChevronLeft, Clock3, Compass, Download, File, FileAudio, FileVideo, Flashlight, FolderOpen, HardDrive, Image as ImageIcon, Languages, LockKeyhole, Menu, Mic, Moon, Music2, NotebookPen, Pause, Play, Plus, Search, Settings, Share2, ShieldCheck, SlidersHorizontal, Sparkles, Sun, Timer, Trash2, Upload, Users, Video, Volume2, X } from 'lucide-react';
import JSZip from 'jszip';
import './index.css';

type Tab = 'home' | 'media' | 'translate' | 'tools' | 'settings';
type Item = { id: string; text: string; done?: boolean; date?: string };
type Contact = { id: string; name: string; phone: string };
type Cue = { id: string; start: number; end: number; source: string; text: string };
type Config = { name: string; accent: string; background: string; logo: string; disabled: string[] };
type Log = { action: string; created_at: string };
const defaultConfig: Config = { name: 'Habib Super App', accent: '#6958df', background: '', logo: '', disabled: [] };
const tools = [
  { id: 'files', title: 'مدیریت فایل', en: 'Files', icon: FolderOpen, group: 'فایل و رسانه' },
  { id: 'images', title: 'ویرایش تصویر', en: 'Photo editor', icon: ImageIcon, group: 'فایل و رسانه' },
  { id: 'zip', title: 'فشرده‌سازی ZIP', en: 'ZIP archive', icon: Archive, group: 'فایل و رسانه' },
  { id: 'download', title: 'دانلود از لینک', en: 'Direct download', icon: Download, group: 'فایل و رسانه' },
  { id: 'calculator', title: 'ماشین‌حساب', en: 'Calculator', icon: Calculator, group: 'ابزارهای روزمره' },
  { id: 'notes', title: 'یادداشت‌ها', en: 'Notes', icon: NotebookPen, group: 'ابزارهای روزمره' },
  { id: 'tasks', title: 'کارهای روزانه', en: 'Tasks', icon: Check, group: 'ابزارهای روزمره' },
  { id: 'calendar', title: 'تقویم', en: 'Calendar', icon: CalendarDays, group: 'ابزارهای روزمره' },
  { id: 'clock', title: 'ساعت و زمان‌سنج', en: 'Clock & timer', icon: Timer, group: 'ابزارهای روزمره' },
  { id: 'contacts', title: 'مخاطبین شخصی', en: 'Contacts', icon: Users, group: 'شخصی و دستگاه' },
  { id: 'vault', title: 'صندوق رمزها', en: 'Password vault', icon: LockKeyhole, group: 'شخصی و دستگاه' },
  { id: 'recorder', title: 'ضبط صدا', en: 'Voice recorder', icon: Mic, group: 'شخصی و دستگاه' },
  { id: 'speech', title: 'گفتار و متن', en: 'Speech & text', icon: AudioLines, group: 'شخصی و دستگاه' },
  { id: 'flashlight', title: 'چراغ‌قوه', en: 'Flashlight', icon: Flashlight, group: 'شخصی و دستگاه' },
  { id: 'compass', title: 'جهت‌یاب', en: 'Compass', icon: Compass, group: 'شخصی و دستگاه' },
  { id: 'storage', title: 'حافظه برنامه', en: 'Storage', icon: HardDrive, group: 'شخصی و دستگاه' },
];
const uid = () => crypto.randomUUID();
function stored<T>(key: string, fallback: T): T { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; } }
function useSaved<T>(key: string, fallback: T) { const [value, setValue] = useState<T>(() => stored(key, fallback)); useEffect(() => { localStorage.setItem(key, JSON.stringify(value)); }, [key, value]); return [value, setValue] as const; }
function saveBlob(blob: Blob, name: string) { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 60000); }
function fmt(seconds: number) { const s = Math.max(0, Math.floor(seconds)); return `${String(Math.floor(s / 3600)).padStart(2, '0')}:${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`; }
function stamp(seconds: number) { return fmt(seconds) + ',' + String(Math.round((seconds % 1) * 1000)).padStart(3, '0'); }
function parseSrt(text: string): Cue[] { return text.replace(/\r/g, '').trim().split(/\n\s*\n/).map(block => { const lines = block.split('\n'); const index = lines.findIndex(line => line.includes('-->')); if (index < 0) return null; const parts = lines[index].split('-->').map(part => part.trim()); const toSeconds = (s: string) => { const m = s.match(/(\d+):(\d+):(\d+)[,.](\d+)/); return m ? Number(m[1]) * 3600 + Number(m[2]) * 60 + Number(m[3]) + Number(m[4]) / 1000 : 0; }; return { id: uid(), start: toSeconds(parts[0]), end: toSeconds(parts[1]), source: '', text: lines.slice(index + 1).join('\n') }; }).filter((c): c is Cue => c !== null); }
function bytes(n: number) { return n < 1048576 ? `${(n / 1024).toFixed(1)} KB` : `${(n / 1048576).toFixed(1)} MB`; }
function downloadText(text: string, name: string, mime = 'text/plain;charset=utf-8') { saveBlob(new Blob([text], { type: mime }), name); }
function normalizeDigits(s: string) { return s.replace(/[۰-۹]/g, c => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g, c => String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))); }

function App() {
  const [tab, setTab] = useState<Tab>('home');
  const [tool, setTool] = useState('');
  const [query, setQuery] = useState('');
  const [dark, setDark] = useSaved('habib-dark', true);
  const [lang, setLang] = useSaved<'fa' | 'en'>('habib-lang', 'fa');
  const [fontSize, setFontSize] = useSaved('habib-font', 16);
  const [notes, setNotes] = useSaved<Item[]>('habib-notes', []);
  const [tasks, setTasks] = useSaved<Item[]>('habib-tasks', []);
  const [events, setEvents] = useSaved<Item[]>('habib-events', []);
  const [contacts, setContacts] = useSaved<Contact[]>('habib-contacts', []);
  const [config, setConfig] = useState<Config>(defaultConfig);
  const [configError, setConfigError] = useState(false);
  const [adminPage, setAdminPage] = useState(location.pathname === '/habib-panel');
  const [adminToken, setAdminToken] = useState(() => sessionStorage.getItem('habib-admin') || '');
  const [adminLog, setAdminLog] = useState<Log[]>([]);
  const [message, setMessage] = useState('');
  const [menuOpen, setMenuOpen] = useState(false);
  const [files, setFiles] = useState<File[]>([]);
  const [fileSearch, setFileSearch] = useState('');
  const [videoSrc, setVideoSrc] = useState('');
  const [audioSrc, setAudioSrc] = useState('');
  const [directLink, setDirectLink] = useState('');
  const [cues, setCues] = useSaved<Cue[]>('habib-cues', []);
  const [currentTime, setCurrentTime] = useState(0);
  const [subtitleOn, setSubtitleOn] = useState(true);
  const [dubOn, setDubOn] = useState(false);
  const [subSize, setSubSize] = useSaved('habib-sub-size', 22);
  const [subColor, setSubColor] = useSaved('habib-sub-color', '#ffffff');
  const [subFont, setSubFont] = useSaved('habib-sub-font', 'Vazirmatn');
  const [subOffset, setSubOffset] = useSaved('habib-sub-offset', 0);
  const [originalVolume, setOriginalVolume] = useSaved('habib-original-volume', 1);
  const [voiceVolume, setVoiceVolume] = useSaved('habib-voice-volume', 1);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [selectedVoice, setSelectedVoice] = useState('');
  const [draftCue, setDraftCue] = useState('');
  const videoRef = useRef<HTMLVideoElement>(null);
  const lastSpoken = useRef('');
  const [loadingAdmin, setLoadingAdmin] = useState(false);

  useEffect(() => { document.documentElement.classList.toggle('dark', dark); }, [dark]);
  useEffect(() => { document.documentElement.lang = lang; document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr'; document.documentElement.style.fontSize = `${fontSize}px`; }, [lang, fontSize]);
  useEffect(() => { fetch('/api/config').then(r => { if (!r.ok) throw Error(); return r.json(); }).then(setConfig).catch(() => setConfigError(true)); }, []);
  useEffect(() => { const onPop = () => setAdminPage(location.pathname === '/habib-panel'); addEventListener('popstate', onPop); return () => removeEventListener('popstate', onPop); }, []);
  useEffect(() => { if (!('speechSynthesis' in window)) return; const update = () => setVoices(speechSynthesis.getVoices().filter(v => v.lang.toLowerCase().startsWith('fa'))); update(); speechSynthesis.addEventListener('voiceschanged', update); return () => speechSynthesis.removeEventListener('voiceschanged', update); }, []);
  useEffect(() => { if (videoRef.current) videoRef.current.volume = originalVolume; }, [originalVolume, videoSrc, tab]);
  useEffect(() => { if (!adminPage || !adminToken) return; adminRequest('/api/admin/state', adminToken).then(data => { setConfig(data.settings); setAdminLog(data.activities); }).catch(() => { setAdminToken(''); sessionStorage.removeItem('habib-admin'); }); }, [adminPage, adminToken]);
  useEffect(() => { if (!message) return; const id = setTimeout(() => setMessage(''), 5000); return () => clearTimeout(id); }, [message]);
  useEffect(() => () => { window.speechSynthesis?.cancel(); }, []);
  const activeCue = [...cues].sort((a, b) => a.start - b.start).find(c => currentTime >= c.start + subOffset && currentTime <= c.end + subOffset);
  function handleTime(time: number) {
    setCurrentTime(time);
    const cue = [...cues].sort((a, b) => a.start - b.start).find(c => time >= c.start + subOffset && time <= c.end + subOffset);
    if (dubOn && cue?.text && lastSpoken.current !== cue.id && 'speechSynthesis' in window) {
      window.speechSynthesis?.cancel();
      const utterance = new SpeechSynthesisUtterance(cue.text);
      utterance.lang = 'fa-IR'; utterance.volume = voiceVolume;
      const chosen = voices.find(v => v.name === selectedVoice); if (chosen) utterance.voice = chosen;
      speechSynthesis.speak(utterance); lastSpoken.current = cue.id;
    }
    if (!cue) lastSpoken.current = '';
  }
  function openAdmin() { history.pushState({}, '', '/habib-panel'); setAdminPage(true); setTab('home'); }
  function closeAdmin() { history.pushState({}, '', '/'); setAdminPage(false); }
  function go(next: Tab) { setTab(next); setTool(''); setMenuOpen(false); window.speechSynthesis?.cancel(); }
  function selectLocalMedia(file: File) { const url = URL.createObjectURL(file); if (file.type.startsWith('video/')) { if (videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc); setVideoSrc(url); go('translate'); } else if (file.type.startsWith('audio/')) { if (audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc); setAudioSrc(url); go('media'); } else { URL.revokeObjectURL(url); setMessage('برای باز کردن این نوع فایل از ابزار مناسب استفاده کنید.'); } }
  function chooseTool(id: string) { setTool(id); setTab('tools'); setMenuOpen(false); }
  const available = tools.filter(t => !config.disabled.includes(t.id));
  const resultTools = available.filter(t => (t.title + ' ' + t.en).toLowerCase().includes(query.toLowerCase()));
  async function exportBackup() { const data = { version: 1, notes, tasks, events, contacts, cues, vault: localStorage.getItem('habib-vault') }; downloadText(JSON.stringify(data, null, 2), 'habib-backup.json', 'application/json'); setMessage('فایل پشتیبان در پوشهٔ دانلود ذخیره شد.'); }
  async function restoreBackup(file?: File) { if (!file) return; try { const data = JSON.parse(await file.text()); if (data.version !== 1 || !Array.isArray(data.notes) || !Array.isArray(data.tasks) || !Array.isArray(data.contacts) || !Array.isArray(data.cues)) throw Error(); if (!confirm('اطلاعات فعلی با نسخهٔ پشتیبان جایگزین شود؟')) return; setNotes(data.notes); setTasks(data.tasks); setContacts(data.contacts); setCues(data.cues); setEvents(Array.isArray(data.events) ? data.events : []); if (typeof data.vault === 'string') localStorage.setItem('habib-vault', data.vault); setMessage('اطلاعات شخصی بازیابی شد.'); } catch { setMessage('فایل پشتیبان معتبر نیست.'); } }
  const rootStyle = { '--accent': config.accent } as React.CSSProperties;
  const title = lang === 'fa' ? 'فضای شخصی شما، یک‌جا' : 'Your everyday space, all in one place';

  return <div className="app-shell" style={rootStyle}>
    <div className="ambient ambient-one"/><div className="ambient ambient-two"/>
    <header className="topbar"><div className="container topbar-inner">
      <button className="icon-btn mobile-menu" data-testid="menu-toggle" aria-label="منو" onClick={() => setMenuOpen(!menuOpen)}><Menu size={22}/></button>
      <button className="brand" data-testid="home-brand" onClick={() => adminPage ? closeAdmin() : go('home')}><span className="brand-mark"><img src={config.logo || 'https://s3.thr3.sotoon.ir/app-builder/icons/1438f59d-7ad7-440a-bd14-b40a6d675b4f/mwch85js.png'} alt=""/></span><span className="brand-copy"><strong>{config.name}</strong><small>YOUR EVERYDAY UNIVERSE</small></span></button>
      <nav className={'desktop-nav ' + (menuOpen ? 'is-open' : '')} aria-label="بخش‌ها">{([['home','خانه'],['media','رسانه'],['translate','Movie Translator'],['tools','ابزارها'],['settings','تنظیمات']] as [Tab,string][]).map(([key,label]) => <button key={key} data-testid={'nav-' + key} onClick={() => { if (adminPage) closeAdmin(); go(key); }} className={tab === key && !adminPage ? 'active' : ''}>{label}</button>)}</nav>
      <div className="top-actions"><button className="icon-btn" data-testid="theme-toggle" title="تغییر پوسته" onClick={() => setDark(!dark)}>{dark ? <Sun size={20}/> : <Moon size={20}/>}</button><span className="top-avatar">H</span></div>
    </div></header>
    {message && <div className="toast" data-testid="status-message" role="status">{message}<button aria-label="بستن" data-testid="dismiss-message" onClick={() => setMessage('')}><X size={16}/></button></div>}
    <main className="container main-content">
      {adminPage ? <AdminPanel token={adminToken} setToken={setAdminToken} config={config} setConfig={setConfig} logs={adminLog} setLogs={setAdminLog} busy={loadingAdmin} setBusy={setLoadingAdmin} onClose={closeAdmin} notify={setMessage} backup={exportBackup} restore={restoreBackup}/> : <>
      {tab === 'home' && <>
        <section className="hero" style={config.background ? { backgroundImage: `linear-gradient(90deg, rgba(21,19,49,.94), rgba(39,34,89,.73)), url("${config.background.replace(/"/g, '')}")` } : undefined}><div className="hero-copy"><div className="eyebrow"><span className="live-dot"/> HABIB SUPER APP <span className="eyebrow-line"/> دنیای ابزارهای شما</div><h1>{title}</h1><p>از مدیریت کارهای روزانه تا تماشای فیلم و ویرایش زیرنویس؛ هر چیزی که لازم دارید، در یک فضای ساده و مرتب.</p><div className="hero-actions"><button className="primary-btn" data-testid="hero-tools" onClick={() => go('tools')}>کاوش ابزارها <ArrowLeft size={18}/></button><button className="ghost-btn" data-testid="hero-translate" onClick={() => go('translate')}><Play size={17}/> بخش فیلم و زیرنویس</button></div><div className="hero-stats"><span><strong>{available.length}+</strong> ابزار کاربردی</span><i/><span><strong>بدون ورود</strong> شروع فوری</span><i/><span><strong>آفلاین</strong> برای ابزارهای شخصی</span></div></div><div className="hero-visual" aria-hidden="true"><div className="orb"><div className="orb-core">H</div><div className="orbit orbit-a"/><div className="orbit orbit-b"/></div><span className="float-icon fi-one"><Music2/></span><span className="float-icon fi-two"><CalendarDays/></span><span className="float-icon fi-three"><Video/></span><span className="float-icon fi-four"><NotebookPen/></span></div></section>
        <div className="section-head"><div><div className="section-kicker">QUICK ACCESS</div><h2>همه‌چیز دمِ دست شما</h2><p>ابزار مورد نظرتان را پیدا کنید و مستقیم وارد شوید.</p></div><button className="text-link" data-testid="all-tools" onClick={() => go('tools')}>مشاهده همه ابزارها <ChevronLeft size={18}/></button></div>
        <div className="search-wrap"><Search size={20}/><input data-testid="home-search" value={query} onChange={e => setQuery(e.target.value)} placeholder="دنبال چه ابزاری می‌گردید؟"/><kbd>جست‌وجوی سریع</kbd></div>
        <div className="tool-grid">{resultTools.slice(0, query ? 16 : 8).map(t => <button className="tool-card" data-testid={'tool-' + t.id} key={t.id} onClick={() => chooseTool(t.id)}><span className="tool-icon"><t.icon size={25}/></span><strong>{lang === 'fa' ? t.title : t.en}</strong><small>{t.group}</small><span className="card-arrow"><ArrowLeft size={16}/></span></button>)}{resultTools.length === 0 && <div className="empty">ابزاری با این نام پیدا نشد.</div>}</div>
        <section className="feature-banner"><div className="feature-icon"><Languages size={29}/></div><div><span className="section-kicker">MOVIE TRANSLATOR</span><h2>زیرنویس و صدای فارسی، کنار فیلم شما</h2><p>فیلم را انتخاب کنید، زیرنویس SRT را وارد یا ویرایش کنید و در صورت پشتیبانی دستگاه، متن فارسی را بشنوید.</p></div><button className="primary-btn" data-testid="feature-translate" onClick={() => go('translate')}>شروع کنید <ArrowLeft size={18}/></button></section>
      </>}
      {tab === 'tools' && !tool && <><PageTitle kicker="TOOLBOX" title="جعبه ابزار شما" subtitle="ابزارهای کاربردی برای کارهای کوچک و بزرگ روزانه"/><div className="search-wrap"><Search size={20}/><input data-testid="tools-search" value={query} onChange={e => setQuery(e.target.value)} placeholder="جست‌وجو میان ابزارها"/></div>{['فایل و رسانه','ابزارهای روزمره','شخصی و دستگاه'].map(group => <section key={group} className="tool-section"><h2>{group}</h2><div className="tool-grid">{resultTools.filter(t => t.group === group).map(t => <button className="tool-card" data-testid={'tool-' + t.id} key={t.id} onClick={() => chooseTool(t.id)}><span className="tool-icon"><t.icon size={25}/></span><strong>{lang === 'fa' ? t.title : t.en}</strong><small>{t.en}</small><span className="card-arrow"><ArrowLeft size={16}/></span></button>)}</div></section>)}{resultTools.length === 0 && <div className="empty">ابزاری پیدا نشد.</div>}</>}
      {tab === 'tools' && tool && !config.disabled.includes(tool) && <><button className="back-link" data-testid="back-tools" onClick={() => setTool('')}><ArrowLeft size={17}/> بازگشت به ابزارها</button><PageTitle kicker="HABIB TOOLS" title={tools.find(t => t.id === tool)?.title || 'ابزار'} subtitle={tools.find(t => t.id === tool)?.en || ''}/><div className="work-panel"><ToolContent id={tool} files={files} setFiles={setFiles} fileSearch={fileSearch} setFileSearch={setFileSearch} chooseMedia={selectLocalMedia} directLink={directLink} setDirectLink={setDirectLink} notes={notes} setNotes={setNotes} tasks={tasks} setTasks={setTasks} contacts={contacts} setContacts={setContacts} events={events} setEvents={setEvents} notify={setMessage}/></div></>}
      {tab === 'tools' && tool && config.disabled.includes(tool) && <div className="empty">این ابزار توسط مدیر غیرفعال شده است. <button className="text-link" data-testid="disabled-tool-back" onClick={() => setTool('')}>بازگشت به ابزارها</button></div>}
      {tab === 'media' && <><PageTitle kicker="MEDIA PLAYER" title="دنیای رسانه" subtitle="موسیقی و ویدیوی انتخابی خودتان را پخش کنید"/><div className="media-grid"><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><Music2/></span><div><h2>پخش موسیقی</h2><p>فایل صوتی را از دستگاه انتخاب کنید.</p></div></div><label className="upload-box" data-testid="audio-picker-label"><Upload size={27}/><strong>انتخاب موسیقی از گوشی</strong><small>MP3، WAV و فرمت‌های قابل پخش دستگاه</small><input data-testid="audio-picker" type="file" accept="audio/*" onChange={e => { const f = e.target.files?.[0]; if (f) { if (audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc); setAudioSrc(URL.createObjectURL(f)); } }}/></label>{audioSrc ? <audio data-testid="audio-player" controls src={audioSrc} className="w-full mt-5"/> : <p className="muted mt-4">هنوز فایلی انتخاب نشده است.</p>}</div><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><FileVideo/></span><div><h2>پخش ویدیو</h2><p>ویدیوی محلی یا لینک مستقیم را باز کنید.</p></div></div><label className="upload-box" data-testid="video-picker-label"><Upload size={27}/><strong>انتخاب فیلم از گوشی</strong><small>فرمت‌های قابل پخش مرورگر دستگاه</small><input data-testid="video-picker" type="file" accept="video/*" onChange={e => { const f = e.target.files?.[0]; if (f) { if (videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc); setVideoSrc(URL.createObjectURL(f)); } }}/></label><div className="input-action mt-4"><input data-testid="video-url" value={directLink} onChange={e => setDirectLink(e.target.value)} dir="ltr" placeholder="https://example.com/video.mp4"/><button data-testid="open-video-url" className="secondary-btn" onClick={() => { try { const url = new URL(directLink); if (!['https:', 'http:'].includes(url.protocol)) throw Error(); setVideoSrc(url.href); } catch { setMessage('لینک معتبر http یا https وارد کنید.'); } }}>باز کردن</button></div></div></div>{videoSrc && <div className="work-panel mt-5"><video data-testid="media-video-player" className="video-player" src={videoSrc} controls playsInline/><button className="text-link mt-4" data-testid="edit-video-subtitles" onClick={() => go('translate')}>ویرایش زیرنویس این فیلم <ChevronLeft size={17}/></button></div>}</>}
      {tab === 'translate' && <><PageTitle kicker="MOVIE TRANSLATOR" title="فیلم، زیرنویس و صدای فارسی" subtitle="ویرایش و نمایش زیرنویس هم‌زمان با فیلم؛ صدای فارسی با موتور گفتار دستگاه"/><div className="notice"><ShieldCheck size={20}/><span>ترجمهٔ خودکار و استخراج گفتار از صدای فیلم در این نسخه وجود ندارد. متن ترجمه‌شده را خودتان وارد کنید یا فایل SRT آماده بارگذاری کنید. صدای فارسی به صداهای نصب‌شده روی دستگاه وابسته است.</span></div><div className="translator-grid"><div className="translator-main"><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><Video/></span><div><h2>نمایش فیلم</h2><p>ویدیوی دستگاه یا لینک مستقیم را باز کنید.</p></div></div><div className="input-action"><label className="secondary-btn file-btn">انتخاب فیلم<input data-testid="translator-video-picker" type="file" accept="video/*" onChange={e => { const f = e.target.files?.[0]; if (f) { if (videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc); setVideoSrc(URL.createObjectURL(f)); } }}/></label><input data-testid="translator-video-url" dir="ltr" placeholder="لینک مستقیم ویدیو" value={directLink} onChange={e => setDirectLink(e.target.value)}/><button className="secondary-btn" data-testid="translator-open-url" onClick={() => { try { const url = new URL(directLink); if (!['http:', 'https:'].includes(url.protocol)) throw Error(); setVideoSrc(url.href); } catch { setMessage('لینک ویدیو معتبر نیست.'); } }}>باز کردن</button></div><div className="video-stage">{videoSrc ? <><video ref={videoRef} data-testid="translator-player" src={videoSrc} controls playsInline onTimeUpdate={e => handleTime(e.currentTarget.currentTime)} onPause={() => window.speechSynthesis?.cancel()} onSeeked={() => { lastSpoken.current = ''; window.speechSynthesis?.cancel(); }}/>{subtitleOn && activeCue?.text && <div data-testid="active-subtitle" className="subtitle-overlay" style={{ color: subColor, fontSize: subSize, fontFamily: subFont }}>{activeCue.text}</div>}</> : <div className="video-placeholder"><Play size={42}/><span>برای شروع یک فیلم انتخاب کنید</span></div>}</div><div className="media-meta"><span>زمان: {fmt(currentTime)}</span><span>{cues.length} خط زیرنویس</span></div></div><div className="work-panel mt-5"><div className="panel-heading"><span className="mini-icon"><Languages/></span><div><h2>ویرایش زیرنویس</h2><p>زمان هر خط را با زمان فعلی فیلم هماهنگ کنید.</p></div></div><div className="input-action"><label className="secondary-btn file-btn">بارگذاری SRT<input data-testid="srt-picker" type="file" accept=".srt,text/plain" onChange={async e => { const f = e.target.files?.[0]; if (f) { const parsed = parseSrt(await f.text()); setCues(parsed); setMessage(parsed.length ? `${parsed.length} خط زیرنویس بارگذاری شد.` : 'زمان‌بندی معتبری در فایل پیدا نشد.'); } }}/></label><button className="secondary-btn" data-testid="export-srt" onClick={() => { if (!cues.length) return setMessage('ابتدا زیرنویس اضافه کنید.'); downloadText([...cues].sort((a,b) => a.start-b.start).map((c,i) => `${i+1}\n${stamp(c.start)} --> ${stamp(c.end)}\n${c.text}`).join('\n\n'), 'habib-subtitles-fa.srt'); setMessage('زیرنویس در پوشهٔ دانلود ذخیره شد.'); }}>دریافت SRT <Download size={16}/></button></div><div className="input-action mt-5"><input data-testid="subtitle-draft" value={draftCue} onChange={e => setDraftCue(e.target.value)} placeholder="متن فارسی زیرنویس جدید..."/><button className="primary-btn" data-testid="add-subtitle" onClick={() => { if (!draftCue.trim()) return setMessage('متن زیرنویس را بنویسید.'); setCues([...cues, { id: uid(), start: currentTime, end: currentTime + 4, text: draftCue.trim(), source: '' }]); setDraftCue(''); }}>افزودن در {fmt(currentTime)} <Plus size={16}/></button></div><div className="cue-list">{[...cues].sort((a,b) => a.start-b.start).map((c,i) => <div className="cue-row" data-testid={'cue-' + i} key={c.id}><div className="cue-time"><label>شروع <input data-testid={'cue-start-' + i} type="number" step="0.1" min="0" value={c.start} onChange={e => setCues(cues.map(x => x.id === c.id ? {...x,start:Number(e.target.value)} : x))}/></label><label>پایان <input data-testid={'cue-end-' + i} type="number" step="0.1" min="0" value={c.end} onChange={e => setCues(cues.map(x => x.id === c.id ? {...x,end:Number(e.target.value)} : x))}/></label></div><textarea data-testid={'cue-text-' + i} aria-label="متن زیرنویس" value={c.text} onChange={e => setCues(cues.map(x => x.id === c.id ? {...x,text:e.target.value} : x))}/><button className="icon-btn danger" data-testid={'cue-delete-' + i} aria-label="حذف خط" onClick={() => setCues(cues.filter(x => x.id !== c.id))}><Trash2 size={17}/></button></div>)}{!cues.length && <div className="empty">زیرنویسی ثبت نشده؛ فایل SRT بارگذاری کنید یا یک خط اضافه کنید.</div>}</div></div></div><aside className="translator-aside"><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><SlidersHorizontal/></span><div><h2>تنظیم زیرنویس</h2><p>ظاهر و هماهنگی تصویر</p></div></div><label className="switch-row">نمایش زیرنویس<input data-testid="subtitle-toggle" type="checkbox" checked={subtitleOn} onChange={e => setSubtitleOn(e.target.checked)}/></label><label className="field-label">اندازه: {subSize}px<input data-testid="subtitle-size" type="range" min="14" max="42" value={subSize} onChange={e => setSubSize(Number(e.target.value))}/></label><label className="field-label">رنگ متن<input data-testid="subtitle-color" type="color" value={subColor} onChange={e => setSubColor(e.target.value)}/></label><label className="field-label">فونت<select data-testid="subtitle-font" value={subFont} onChange={e => setSubFont(e.target.value)}><option value="Vazirmatn">وزیرمتن</option><option value="sans-serif">ساده</option><option value="serif">کلاسیک</option></select></label><label className="field-label">جابجایی زمان (ثانیه)<input data-testid="subtitle-offset" type="number" step="0.1" value={subOffset} onChange={e => setSubOffset(Number(e.target.value))}/></label></div><div className="work-panel mt-5"><div className="panel-heading"><span className="mini-icon"><Volume2/></span><div><h2>Persian Voice Translator</h2><p>خواندن متن فارسی روی فیلم</p></div></div><label className="switch-row">پخش صدای فارسی<input data-testid="dub-toggle" type="checkbox" checked={dubOn} onChange={e => { setDubOn(e.target.checked); if (!e.target.checked) window.speechSynthesis?.cancel(); }}/></label><label className="field-label">صدای اصلی فیلم: {Math.round(originalVolume*100)}٪<input data-testid="original-volume" type="range" min="0" max="1" step="0.05" value={originalVolume} onChange={e => setOriginalVolume(Number(e.target.value))}/></label><label className="field-label">صدای فارسی: {Math.round(voiceVolume*100)}٪<input data-testid="voice-volume" type="range" min="0" max="1" step="0.05" value={voiceVolume} onChange={e => setVoiceVolume(Number(e.target.value))}/></label><label className="field-label">گوینده فارسی<select data-testid="voice-select" value={selectedVoice} onChange={e => setSelectedVoice(e.target.value)}><option value="">صدای پیش‌فرض دستگاه</option>{voices.map(v => <option key={v.name} value={v.name}>{v.name}</option>)}</select></label><p className="help-text">{voices.length ? `${voices.length} صدای فارسی در دستگاه پیدا شد.` : 'ممکن است صدای فارسی روی این دستگاه نصب نباشد.'} پخش گفتار ممکن است با ویدیو دقیقاً هم‌زمان نشود. خروجی صوتی یا ویدیوی دوبله‌شده از موتور گفتار دستگاه قابل دریافت نیست.</p></div></aside></div></>}
      {tab === 'settings' && <><PageTitle kicker="PREFERENCES" title="تنظیمات شما" subtitle="برنامه را مطابق سلیقه خودتان تنظیم کنید"/><div className="settings-grid"><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><Settings/></span><div><h2>ظاهر و زبان</h2><p>تنظیمات روی همین دستگاه می‌مانند.</p></div></div><label className="switch-row">حالت تاریک<input data-testid="settings-theme" type="checkbox" checked={dark} onChange={e => setDark(e.target.checked)}/></label><label className="field-label">زبان راهبری<select data-testid="language-select" value={lang} onChange={e => setLang(e.target.value as 'fa' | 'en')}><option value="fa">فارسی</option><option value="en">English (navigation)</option></select></label><p className="help-text">در حال حاضر فقط عنوان ابزارها و عنوان صفحه اصلی انگلیسی می‌شوند؛ محتوای ابزارها فارسی است.</p><label className="field-label">اندازه نوشته‌ها: {fontSize}px<input data-testid="font-size" type="range" min="14" max="20" value={fontSize} onChange={e => setFontSize(Number(e.target.value))}/></label></div><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><HardDrive/></span><div><h2>اطلاعات و پشتیبان‌گیری</h2><p>یادداشت‌ها، کارها، مخاطبین و زیرنویس‌ها</p></div></div><div className="stack-actions"><button className="secondary-btn" data-testid="backup-export" onClick={exportBackup}><Download size={17}/> دریافت پشتیبان</button><label className="secondary-btn file-btn">بازیابی پشتیبان<input data-testid="backup-import" type="file" accept=".json,application/json" onChange={e => restoreBackup(e.target.files?.[0])}/></label><button className="secondary-btn" data-testid="storage-open" onClick={() => chooseTool('storage')}><HardDrive size={17}/> وضعیت حافظه</button></div><p className="help-text">فایل‌های انتخابی گوشی در پشتیبان نمی‌آیند؛ صندوق رمز به‌صورت رمزگذاری‌شده ذخیره می‌شود و برای بازگشایی به گذرواژهٔ خودش نیاز دارد.</p></div></div>{configError && <div className="notice mt-5">تنظیمات عمومی فعلاً دریافت نشد؛ تنظیمات شخصی روی همین دستگاه همچنان کار می‌کنند. <button data-testid="retry-config" onClick={() => { setConfigError(false); fetch('/api/config').then(r => r.json()).then(setConfig).catch(() => setConfigError(true)); }}>تلاش دوباره</button></div>}</>}
      </>}
    </main>
    <footer className="footer"><div className="container footer-inner"><span><span className="footer-h">H.</span> Habib Super App <span className="footer-divider">·</span> ساخته‌شده برای روزهای پرکار شما</span><button className="footer-admin" data-testid="admin-entry" onClick={openAdmin}>ورود مدیریت</button></div></footer>
    {!adminPage && <nav className="bottom-nav" aria-label="راهبری موبایل">{([['home','خانه',Sparkles],['media','رسانه',Music2],['translate','فیلم',Video],['tools','ابزارها',FolderOpen],['settings','تنظیمات',Settings]] as const).map(([key,label,Icon]) => <button key={key} data-testid={'mobile-nav-' + key} className={tab === key ? 'active' : ''} onClick={() => go(key)}><Icon size={21}/><span>{label}</span></button>)}</nav>}
  </div>;
}

function PageTitle({ kicker, title, subtitle }: { kicker: string; title: string; subtitle: string }) { return <div className="page-title"><span className="section-kicker">{kicker}</span><h1>{title}</h1><p>{subtitle}</p></div>; }
async function adminRequest(path: string, token: string, method = 'GET', payload?: unknown) { const res = await fetch(path, { method, headers: { 'Content-Type': 'application/json', 'x-admin-token': token }, body: payload === undefined ? undefined : JSON.stringify(payload) }); const data = await res.json(); if (!res.ok) throw new Error(data.error || 'درخواست انجام نشد.'); return data; }

function AdminPanel({ token, setToken, config, setConfig, logs, setLogs, busy, setBusy, onClose, notify, backup, restore }: { token: string; setToken: (s: string) => void; config: Config; setConfig: (s: Config) => void; logs: Log[]; setLogs: (s: Log[]) => void; busy: boolean; setBusy: (b: boolean) => void; onClose: () => void; notify: (s: string) => void; backup: () => void; restore: (f?: File) => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [draft, setDraft] = useState(config); const [oldPassword, setOldPassword] = useState(''); const [newPassword, setNewPassword] = useState('');
  useEffect(() => setDraft(config), [config]);
  async function login(e: React.FormEvent) { e.preventDefault(); setError(''); setBusy(true); try { const res = await fetch('/api/admin/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, password }) }); const data = await res.json(); if (!res.ok) throw new Error(data.error); sessionStorage.setItem('habib-admin', data.token); setToken(data.token); setPassword(''); notify('به پنل مدیریت خوش آمدید.'); } catch (err) { setError((err as Error).message || 'ورود انجام نشد.'); } finally { setBusy(false); } }
  async function save() { setBusy(true); setError(''); try { const next = await adminRequest('/api/admin/config', token, 'PUT', draft); setConfig(next); setDraft(next); notify('تنظیمات عمومی ذخیره شد.'); const state = await adminRequest('/api/admin/state', token); setLogs(state.activities); } catch (err) { setError((err as Error).message); } finally { setBusy(false); } }
  async function changePassword(e: React.FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await adminRequest('/api/admin/password', token, 'POST', { oldPassword, newPassword }); sessionStorage.removeItem('habib-admin'); setToken(''); setOldPassword(''); setNewPassword(''); notify('رمز عوض شد؛ با رمز جدید دوباره وارد شوید.'); } catch (err) { setError((err as Error).message); } finally { setBusy(false); } }
  async function logout() { try { await adminRequest('/api/admin/logout', token, 'POST'); } catch { /* local sign-out still applies */ } sessionStorage.removeItem('habib-admin'); setToken(''); onClose(); }
  if (!token) return <div className="admin-login work-panel"><div className="admin-shield"><ShieldCheck size={34}/></div><span className="section-kicker">PRIVATE ACCESS</span><h1>ورود مدیریت</h1><p>این بخش فقط برای مدیر برنامه است.</p><form onSubmit={login} className="form-stack"><label className="field-label">نام کاربری<input data-testid="admin-username" autoComplete="username" value={username} onChange={e => setUsername(e.target.value)} required/></label><label className="field-label">رمز عبور<input data-testid="admin-password" type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} required/></label>{error && <p className="form-error" data-testid="admin-error">{error}</p>}<button className="primary-btn full-btn" data-testid="admin-login" disabled={busy}>ورود به پنل <ArrowLeft size={17}/></button></form><button className="text-link centered" data-testid="admin-back" onClick={onClose}>بازگشت به برنامه</button></div>;
  return <><PageTitle kicker="PRIVATE DASHBOARD" title="پنل مدیریت Habib" subtitle="تنظیمات عمومی برنامه و گزارش فعالیت‌ها"/><div className="admin-toolbar"><span className="pill"><ShieldCheck size={15}/> مدیر وارد شده</span><button className="secondary-btn" data-testid="admin-logout" onClick={logout}>خروج از پنل</button></div>{error && <div className="form-error mb-5" data-testid="admin-error">{error}</div>}<div className="settings-grid"><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><SlidersHorizontal/></span><div><h2>هویت برنامه</h2><p>تغییرات برای همه بازدیدکنندگان نمایش داده می‌شوند.</p></div></div><label className="field-label">نام نمایشی داخل برنامه<input data-testid="admin-app-name" value={draft.name} onChange={e => setDraft({...draft,name:e.target.value})}/></label><label className="field-label">رنگ اصلی<input data-testid="admin-accent" type="color" value={draft.accent} onChange={e => setDraft({...draft,accent:e.target.value})}/></label><label className="field-label">نشانی تصویر لوگو (اختیاری)<input data-testid="admin-logo" dir="ltr" placeholder="https://..." value={draft.logo} onChange={e => setDraft({...draft,logo:e.target.value})}/></label><label className="field-label">نشانی تصویر پس‌زمینه (اختیاری)<input data-testid="admin-background" dir="ltr" placeholder="https://..." value={draft.background} onChange={e => setDraft({...draft,background:e.target.value})}/></label><p className="help-text">تغییر نام اینجا فقط نام داخل برنامه را عوض می‌کند؛ نام زیر آیکون نسخهٔ نصب‌شده با ساخت نسخهٔ جدید تغییر می‌کند.</p><button className="primary-btn" data-testid="admin-save" disabled={busy} onClick={save}>ذخیره تنظیمات <Check size={17}/></button></div><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><Settings/></span><div><h2>مدیریت امکانات</h2><p>ابزارهای غیرفعال از فهرست عمومی برداشته می‌شوند.</p></div></div><div className="feature-list">{tools.map(t => <label className="switch-row" key={t.id}>{t.title}<input type="checkbox" data-testid={'admin-feature-' + t.id} checked={!draft.disabled.includes(t.id)} onChange={e => setDraft({...draft,disabled:e.target.checked ? draft.disabled.filter(x => x !== t.id) : [...draft.disabled,t.id]})}/></label>)}</div><button className="primary-btn mt-5" data-testid="admin-save-features" disabled={busy} onClick={save}>ذخیره امکانات <Check size={17}/></button></div><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><LockKeyhole/></span><div><h2>امنیت پنل</h2><p>پس از تغییر رمز، دوباره وارد شوید.</p></div></div><form className="form-stack" onSubmit={changePassword}><label className="field-label">رمز فعلی<input data-testid="admin-old-password" type="password" value={oldPassword} onChange={e => setOldPassword(e.target.value)} required/></label><label className="field-label">رمز جدید (حداقل ۸ نویسه)<input data-testid="admin-new-password" type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} minLength={8} required/></label><button className="secondary-btn" data-testid="admin-change-password" disabled={busy}>تغییر رمز</button></form></div><div className="work-panel"><div className="panel-heading"><span className="mini-icon"><Archive/></span><div><h2>پشتیبان‌گیری اطلاعات شخصی</h2><p>اطلاعات این دستگاه؛ نه اطلاعات سایر کاربران</p></div></div><div className="stack-actions"><button className="secondary-btn" data-testid="admin-backup" onClick={backup}><Download size={17}/> دریافت پشتیبان</button><label className="secondary-btn file-btn">بازیابی<input data-testid="admin-restore" type="file" accept=".json" onChange={e => restore(e.target.files?.[0])}/></label></div><p className="help-text">چون کاربران بدون حساب وارد می‌شوند، اطلاعات شخصی فقط روی دستگاه خودشان است و فهرست حساب‌های کاربری برای مدیریت وجود ندارد.</p></div></div><div className="work-panel mt-5"><div className="panel-heading"><span className="mini-icon"><Activity/></span><div><h2>گزارش فعالیت مدیریت</h2><p>آخرین تغییرات تنظیمات و ورودها</p></div></div>{logs.length ? <div className="log-list">{logs.map((l,i) => <div key={i}><span>{l.action}</span><time>{new Date(l.created_at).toLocaleString('fa-IR')}</time></div>)}</div> : <div className="empty">هنوز گزارشی ثبت نشده است.</div>}</div></>;
}

function ToolContent({ id, files, setFiles, fileSearch, setFileSearch, chooseMedia, directLink, setDirectLink, notes, setNotes, tasks, setTasks, contacts, setContacts, events, setEvents, notify }: { id: string; files: File[]; setFiles: (x: File[]) => void; fileSearch: string; setFileSearch: (x: string) => void; chooseMedia: (f: File) => void; directLink: string; setDirectLink: (x: string) => void; notes: Item[]; setNotes: (x: Item[]) => void; tasks: Item[]; setTasks: (x: Item[]) => void; contacts: Contact[]; setContacts: (x: Contact[]) => void; events: Item[]; setEvents: (x: Item[]) => void; notify: (x: string) => void }) {
  if (id === 'files') return <FilesTool files={files} setFiles={setFiles} fileSearch={fileSearch} setFileSearch={setFileSearch} chooseMedia={chooseMedia} notify={notify}/>;
  if (id === 'zip') return <ZipTool files={files} setFiles={setFiles} notify={notify}/>;
  if (id === 'download') return <><h2>دریافت فایل از لینک مستقیم</h2><p className="muted">لینک مستقیم http یا https را وارد کنید. ممکن است سرور مقصد دریافت را محدود کند.</p><div className="input-action mt-5"><input data-testid="download-url" dir="ltr" value={directLink} onChange={e => setDirectLink(e.target.value)} placeholder="https://example.com/file.zip"/><button data-testid="download-start" className="primary-btn" onClick={() => { try { const url = new URL(directLink); if (!['https:','http:'].includes(url.protocol)) throw Error(); const a = document.createElement('a'); a.href = url.href; a.download = ''; a.rel = 'noopener noreferrer'; a.target = '_blank'; document.body.appendChild(a); a.click(); a.remove(); notify('درخواست دانلود به مرورگر سپرده شد؛ محدودیت‌های سرور مقصد ممکن است مانع ذخیره شود.'); } catch { notify('لینک معتبر وارد کنید.'); } }}>دریافت <Download size={17}/></button></div></>;
  if (id === 'notes') return <ListTool title="یادداشت‌های من" placeholder="یک یادداشت تازه بنویسید..." items={notes} setItems={setNotes} test="notes" notify={notify}/>;
  if (id === 'tasks') return <ListTool title="کارهای امروز" placeholder="کار تازه‌ای اضافه کنید..." items={tasks} setItems={setTasks} test="tasks" checkable notify={notify}/>;
  if (id === 'contacts') return <ContactsTool items={contacts} setItems={setContacts} notify={notify}/>;
  if (id === 'calendar') return <CalendarTool items={events} setItems={setEvents} notify={notify}/>;
  if (id === 'calculator') return <CalculatorTool/>;
  if (id === 'clock') return <ClockTool/>;
  if (id === 'recorder') return <RecorderTool notify={notify}/>;
  if (id === 'speech') return <SpeechTool notify={notify}/>;
  if (id === 'images') return <ImageTool notify={notify}/>;
  if (id === 'vault') return <VaultTool notify={notify}/>;
  if (id === 'flashlight') return <FlashlightTool notify={notify}/>;
  if (id === 'compass') return <CompassTool/>;
  if (id === 'storage') return <StorageTool notes={notes.length} tasks={tasks.length} notify={notify}/>;
  return <div className="empty">این ابزار در دسترس نیست.</div>;
}

function FilesTool({ files, setFiles, fileSearch, setFileSearch, chooseMedia, notify }: { files: File[]; setFiles: (f: File[]) => void; fileSearch: string; setFileSearch: (s: string) => void; chooseMedia: (f: File) => void; notify: (s: string) => void }) {
  async function share(file: File) { try { if (navigator.canShare?.({ files: [file] })) await navigator.share({ files: [file], title: file.name }); else notify('اشتراک‌گذاری خود فایل روی این دستگاه پشتیبانی نمی‌شود.'); } catch (err) { if ((err as Error).name !== 'AbortError') notify('اشتراک‌گذاری انجام نشد.'); } }
  return <><h2>فایل‌های انتخاب‌شده</h2><p className="muted">برای حفظ حریم خصوصی، فقط فایل‌هایی نمایش داده می‌شوند که خودتان انتخاب کرده‌اید؛ برنامه به همه حافظه گوشی دسترسی ندارد.</p><label className="upload-box mt-5"><FolderOpen size={27}/><strong>انتخاب چند فایل</strong><small>پخش، جست‌وجو و اشتراک‌گذاری فایل‌های انتخابی</small><input data-testid="files-picker" type="file" multiple onChange={e => setFiles([...files, ...Array.from(e.target.files || [])])}/></label><div className="search-wrap mt-5"><Search size={18}/><input data-testid="files-search" value={fileSearch} onChange={e => setFileSearch(e.target.value)} placeholder="جست‌وجو در فایل‌های انتخاب‌شده"/></div><div className="file-list">{files.filter(f => f.name.toLowerCase().includes(fileSearch.toLowerCase())).map((f,i) => <div className="file-row" key={i}><span className="mini-icon">{f.type.startsWith('audio') ? <FileAudio/> : f.type.startsWith('video') ? <FileVideo/> : <File/>}</span><div className="file-info"><strong dir="auto">{f.name}</strong><small>{bytes(f.size)}</small></div><div className="row-actions">{(f.type.startsWith('audio/') || f.type.startsWith('video/')) && <button data-testid={'file-open-' + i} className="icon-btn" title="پخش" onClick={() => chooseMedia(f)}><Play size={17}/></button>}<button data-testid={'file-share-' + i} className="icon-btn" title="اشتراک" onClick={() => share(f)}><Share2 size={17}/></button><button data-testid={'file-remove-' + i} className="icon-btn danger" title="حذف از فهرست" onClick={() => setFiles(files.filter(x => x !== f))}><X size={17}/></button></div></div>)}{!files.length && <div className="empty">هنوز فایلی انتخاب نشده است.</div>}</div></>;
}
function ZipTool({ files, setFiles, notify }: { files: File[]; setFiles: (f: File[]) => void; notify: (s: string) => void }) {
  const [working, setWorking] = useState(false); const [archive, setArchive] = useState<File | null>(null); const [entries, setEntries] = useState<{ name: string; blob: Blob }[]>([]);
  async function compress() { if (!files.length) return notify('ابتدا فایل انتخاب کنید.'); setWorking(true); try { const zip = new JSZip(); files.forEach(f => zip.file(f.name, f)); const blob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE', compressionOptions: { level: 6 } }); saveBlob(blob, 'habib-files.zip'); notify('فایل ZIP در پوشهٔ دانلود ذخیره شد.'); } catch { notify('فشرده‌سازی انجام نشد.'); } finally { setWorking(false); } }
  async function extract(f: File) { setWorking(true); setEntries([]); try { if (f.size > 100 * 1048576) throw Error('حجم ZIP بیش از ۱۰۰ مگابایت است.'); const zip = await JSZip.loadAsync(f); const items = Object.values(zip.files).filter(x => !x.dir); if (items.length > 100) throw Error('این بایگانی برای باز کردن در گوشی بیش از حد بزرگ است.'); const result = await Promise.all(items.map(async x => ({ name: x.name, blob: await x.async('blob') }))); if (result.reduce((total, item) => total + item.blob.size, 0) > 100 * 1048576) throw Error('فایل‌های استخراج‌شده بیش از ۱۰۰ مگابایت هستند.'); setEntries(result); notify(`${result.length} فایل از بایگانی خوانده شد.`); } catch (err) { notify((err as Error).message || 'بایگانی معتبر نیست.'); } finally { setWorking(false); } }
  return <><h2>ساخت و باز کردن ZIP</h2><p className="muted">فایل‌ها فقط در همین دستگاه پردازش می‌شوند. برای فایل‌های خیلی حجیم ممکن است حافظه گوشی کافی نباشد.</p><div className="media-grid mt-5"><div><label className="upload-box"><Archive size={28}/><strong>انتخاب فایل برای فشرده‌سازی</strong><input data-testid="zip-files" type="file" multiple onChange={e => setFiles(Array.from(e.target.files || []))}/></label><p className="muted mt-4">{files.length} فایل انتخاب شده</p><button data-testid="zip-create" className="primary-btn mt-4" disabled={working} onClick={compress}>ساخت ZIP <Download size={17}/></button></div><div><label className="upload-box"><FolderOpen size={28}/><strong>انتخاب فایل ZIP برای استخراج</strong><input data-testid="zip-import" type="file" accept=".zip,application/zip" onChange={e => { const f = e.target.files?.[0]; if (f) { setArchive(f); extract(f); } }}/></label><p className="muted mt-4">{archive?.name || 'فایلی انتخاب نشده'}</p></div></div>{working && <p className="muted mt-5">در حال پردازش فایل‌ها...</p>}{entries.length > 0 && <div className="file-list mt-5">{entries.map((e,i) => <div className="file-row" key={i}><File size={20}/><div className="file-info"><strong dir="auto">{e.name}</strong><small>{bytes(e.blob.size)}</small></div><button data-testid={'zip-extract-' + i} className="secondary-btn" onClick={() => saveBlob(e.blob, e.name.split('/').pop() || 'file')}>دریافت</button></div>)}</div>}</>;
}
function ListTool({ title, placeholder, items, setItems, test, checkable, notify }: { title: string; placeholder: string; items: Item[]; setItems: (i: Item[]) => void; test: string; checkable?: boolean; notify: (s: string) => void }) { const [value, setValue] = useState(''); return <><h2>{title}</h2><p className="muted">اطلاعات روی همین دستگاه ذخیره می‌شوند.</p><form className="input-action mt-5" onSubmit={e => { e.preventDefault(); if (!value.trim()) return notify('ابتدا متن را وارد کنید.'); setItems([{ id: uid(), text: value.trim(), done: false },...items]); setValue(''); }}><input data-testid={test + '-input'} value={value} onChange={e => setValue(e.target.value)} placeholder={placeholder}/><button data-testid={test + '-add'} className="primary-btn">افزودن <Plus size={17}/></button></form><div className="item-list">{items.map((item,i) => <div className="item-row" data-testid={test + '-item-' + i} key={item.id}>{checkable && <input data-testid={test + '-check-' + i} type="checkbox" checked={!!item.done} onChange={e => setItems(items.map(x => x.id === item.id ? {...x,done:e.target.checked} : x))}/>}<span className={item.done ? 'completed' : ''}>{item.text}</span><button className="icon-btn danger" data-testid={test + '-delete-' + i} aria-label="حذف" onClick={() => setItems(items.filter(x => x.id !== item.id))}><Trash2 size={17}/></button></div>)}{!items.length && <div className="empty">هنوز موردی ثبت نشده است.</div>}</div></>; }
function ContactsTool({ items, setItems, notify }: { items: Contact[]; setItems: (x: Contact[]) => void; notify: (s: string) => void }) { const [name, setName] = useState(''); const [phone, setPhone] = useState(''); return <><h2>مخاطبین شخصی</h2><p className="muted">این فهرست جدا از مخاطبین سیستم گوشی است و فقط روی همین دستگاه ذخیره می‌شود.</p><form className="input-action mt-5" onSubmit={e => { e.preventDefault(); if (!name.trim() || !phone.trim()) return notify('نام و شماره را وارد کنید.'); setItems([{ id: uid(), name: name.trim(), phone: normalizeDigits(phone.trim()) }, ...items]); setName(''); setPhone(''); }}><input data-testid="contact-name" value={name} onChange={e => setName(e.target.value)} placeholder="نام مخاطب"/><input data-testid="contact-phone" value={phone} onChange={e => setPhone(e.target.value)} dir="ltr" inputMode="tel" placeholder="شماره تماس"/><button className="primary-btn" data-testid="contact-add">افزودن <Plus size={16}/></button></form><div className="item-list">{items.map((c,i) => <div className="item-row" data-testid={'contact-' + i} key={c.id}><span className="contact-avatar">{c.name[0]}</span><span className="file-info"><strong>{c.name}</strong><a data-testid={'contact-call-' + i} href={'tel:' + c.phone} dir="ltr">{c.phone}</a></span><button className="icon-btn danger" data-testid={'contact-delete-' + i} aria-label="حذف" onClick={() => setItems(items.filter(x => x.id !== c.id))}><Trash2 size={17}/></button></div>)}{!items.length && <div className="empty">هنوز مخاطبی اضافه نشده است.</div>}</div></>; }
function CalendarTool({ items, setItems, notify }: { items: Item[]; setItems: (x: Item[]) => void; notify: (s: string) => void }) { const [date, setDate] = useState(new Date().toISOString().slice(0,10)); const [text, setText] = useState(''); return <><h2>تقویم و رویدادها</h2><p className="muted">نمایش تاریخ امروز به تقویم شمسی؛ انتخاب روز در تقویم دستگاه به میلادی است.</p><div className="date-display"><CalendarDays size={29}/><span>{new Date().toLocaleDateString('fa-IR-u-ca-persian', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</span></div><form className="input-action mt-5" onSubmit={e => { e.preventDefault(); if (!text.trim()) return notify('عنوان رویداد را وارد کنید.'); setItems([{ id: uid(), text: text.trim(), date },...items]); setText(''); }}><input data-testid="event-date" type="date" value={date} onChange={e => setDate(e.target.value)}/><input data-testid="event-input" value={text} onChange={e => setText(e.target.value)} placeholder="عنوان رویداد"/><button className="primary-btn" data-testid="event-add">ثبت رویداد</button></form><div className="item-list">{items.filter(x => x.date === date).map((x,i) => <div className="item-row" data-testid={'event-' + i} key={x.id}><span>{x.text}</span><button data-testid={'event-delete-' + i} className="icon-btn danger" onClick={() => setItems(items.filter(y => y.id !== x.id))}><Trash2 size={17}/></button></div>)}{!items.some(x => x.date === date) && <div className="empty">برای این روز رویدادی ثبت نشده است.</div>}</div></>; }
function CalculatorTool() { const [value, setValue] = useState(''); const [error, setError] = useState(''); function press(key: string) { setError(''); if (key === 'C') return setValue(''); if (key === '⌫') return setValue(value.slice(0,-1)); if (key === '=') { try { const exp = normalizeDigits(value).replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-'); if (!/^[\d+\-*/().%\s]+$/.test(exp) || exp.length > 100) throw Error(); const answer = Function('"use strict"; return (' + exp + ')')() as number; if (!Number.isFinite(answer)) throw Error(); setValue(String(Number(answer.toPrecision(12)))); } catch { setError('عبارت قابل محاسبه نیست.'); } return; } if (key === '√' || key === 'x²' || key === 'sin' || key === 'cos') { const n = Number(value); if (!Number.isFinite(n) || (key === '√' && n < 0)) return setError('یک عدد معتبر وارد کنید.'); setValue(String(key === '√' ? Math.sqrt(n) : key === 'x²' ? n*n : key === 'sin' ? Math.sin(n * Math.PI / 180) : Math.cos(n * Math.PI / 180))); return; } setValue(value + key); } return <div className="calculator"><div className="calc-screen"><small>ماشین‌حساب علمی · زاویه برحسب درجه</small><input data-testid="calculator-display" dir="ltr" value={value} onChange={e => setValue(e.target.value)} placeholder="0"/>{error && <span className="form-error">{error}</span>}</div><div className="calc-keys">{['C','⌫','(',')','sin','cos','√','x²','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','%','+','='].map(k => <button key={k} data-testid={'calc-' + k} className={k === '=' ? 'equals' : '+−×÷'.includes(k) ? 'operator' : ''} onClick={() => press(k)}>{k}</button>)}</div></div>; }
function ClockTool() { const [now, setNow] = useState(new Date()); const [running, setRunning] = useState(false); const [elapsed, setElapsed] = useState(0); const [minutes, setMinutes] = useState(5); const [remaining, setRemaining] = useState(300); const [timerOn, setTimerOn] = useState(false); const endRef = useRef(0); const timerEndRef = useRef(0); useEffect(() => { const id = setInterval(() => { setNow(new Date()); if (running) setElapsed(Math.max(0,(Date.now()-endRef.current)/1000)); if (timerOn) { const left = Math.max(0,Math.ceil((timerEndRef.current-Date.now())/1000)); setRemaining(left); if (!left) setTimerOn(false); } },200); return () => clearInterval(id); },[running,timerOn]); return <div className="clock-grid"><section className="time-card"><Clock3 size={28}/><h3>ساعت دیجیتال</h3><div className="time-big" data-testid="digital-clock" dir="ltr">{now.toLocaleTimeString('fa-IR')}</div><p>{now.toLocaleDateString('fa-IR-u-ca-persian', { weekday:'long',year:'numeric',month:'long',day:'numeric' })}</p></section><section className="time-card"><Timer size={28}/><h3>کرنومتر</h3><div className="time-big" data-testid="stopwatch-display" dir="ltr">{fmt(elapsed)}</div><div className="button-row"><button className="secondary-btn" data-testid="stopwatch-toggle" onClick={() => { if (!running) endRef.current = Date.now() - elapsed*1000; setRunning(!running); }}>{running ? 'توقف' : 'شروع'}</button><button className="secondary-btn" data-testid="stopwatch-reset" onClick={() => { setRunning(false); setElapsed(0); }}>بازنشانی</button></div></section><section className="time-card"><Clock3 size={28}/><h3>تایمر</h3><div className="time-big" data-testid="timer-display" dir="ltr">{fmt(remaining)}</div><label className="field-label">دقیقه<input data-testid="timer-minutes" type="number" min="1" max="1440" value={minutes} onChange={e => { const m = Number(e.target.value); setMinutes(m); if (!timerOn) setRemaining(m*60); }}/></label><div className="button-row"><button className="secondary-btn" data-testid="timer-toggle" onClick={() => { if (!timerOn && remaining > 0) timerEndRef.current = Date.now() + remaining*1000; setTimerOn(!timerOn); }}>{timerOn ? 'توقف' : 'شروع'}</button><button className="secondary-btn" data-testid="timer-reset" onClick={() => { setTimerOn(false); setRemaining(minutes*60); }}>بازنشانی</button></div><p className="help-text">تایمر فقط تا وقتی برنامه باز است کار می‌کند.</p></section></div>; }
function RecorderTool({ notify }: { notify: (s: string) => void }) { const [recording, setRecording] = useState(false); const [audio, setAudio] = useState<Blob | null>(null); const recorder = useRef<MediaRecorder | null>(null); const stream = useRef<MediaStream | null>(null); useEffect(() => () => { recorder.current?.stop(); stream.current?.getTracks().forEach(t => t.stop()); },[]); async function toggle() { if (recording) { recorder.current?.stop(); setRecording(false); return; } try { if (!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder) throw Error(); const s = await navigator.mediaDevices.getUserMedia({ audio: true }); stream.current = s; const chunks: BlobPart[] = []; const r = new MediaRecorder(s); recorder.current = r; r.ondataavailable = e => { if (e.data.size) chunks.push(e.data); }; r.onstop = () => { setAudio(new Blob(chunks, { type: r.mimeType || 'audio/webm' })); s.getTracks().forEach(t => t.stop()); }; r.start(); setRecording(true); } catch { notify('میکروفون در دسترس نیست یا اجازهٔ استفاده داده نشد.'); } } const url = audio ? URL.createObjectURL(audio) : ''; useEffect(() => () => { if (url) URL.revokeObjectURL(url); },[url]); return <><h2>ضبط صدا</h2><p className="muted">اجازه میکروفون فقط هنگام شروع ضبط درخواست می‌شود. ضبط در پس‌زمینه یا پس از بستن برنامه ادامه نمی‌یابد.</p><div className={'recorder-circle ' + (recording ? 'recording' : '')}><Mic size={42}/></div><div className="button-row justify-center"><button className="primary-btn" data-testid="record-toggle" onClick={toggle}>{recording ? <><Pause size={18}/> پایان ضبط</> : <><Mic size={18}/> شروع ضبط</>}</button>{audio && <button className="secondary-btn" data-testid="record-download" onClick={() => { saveBlob(audio, audio.type.includes('mp4') ? 'habib-recording.mp4' : 'habib-recording.webm'); notify('ضبط در پوشهٔ دانلود ذخیره شد.'); }}>دریافت صدا</button>}</div>{audio && <audio data-testid="record-playback" controls src={url} className="w-full mt-5"/>}</>; }
function SpeechTool({ notify }: { notify: (s: string) => void }) { const [text, setText] = useState(''); const [listening, setListening] = useState(false); const recognition = useRef<any>(null); useEffect(() => () => { recognition.current?.stop(); window.speechSynthesis?.cancel(); },[]); function listen() { const Speech = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition; if (!Speech) return notify('تشخیص گفتار در مرورگر این دستگاه پشتیبانی نمی‌شود.'); try { const r = new Speech(); recognition.current = r; r.lang = 'fa-IR'; r.continuous = true; r.interimResults = false; r.onresult = (e: any) => { const words = Array.from(e.results).slice(e.resultIndex).map((x: any) => x[0].transcript).join(' '); setText(v => (v ? v + ' ' : '') + words); }; r.onerror = () => { setListening(false); notify('تشخیص گفتار انجام نشد؛ دسترسی میکروفون و اینترنت را بررسی کنید.'); }; r.onend = () => setListening(false); r.start(); setListening(true); } catch { notify('موتور گفتار در دسترس نیست.'); } } function speak() { if (!('speechSynthesis' in window)) return notify('تبدیل متن به گفتار روی این دستگاه پشتیبانی نمی‌شود.'); window.speechSynthesis?.cancel(); const u = new SpeechSynthesisUtterance(text); u.lang = 'fa-IR'; speechSynthesis.speak(u); } return <><h2>گفتار و متن</h2><p className="muted">از موتور گفتار دستگاه یا مرورگر استفاده می‌شود؛ تشخیص گفتار ممکن است به اینترنت نیاز داشته باشد و نوع موتور توسط دستگاه تعیین می‌شود.</p><textarea data-testid="speech-text" className="big-textarea mt-5" value={text} onChange={e => setText(e.target.value)} placeholder="اینجا بنویسید یا با میکروفون صحبت کنید..."/><div className="button-row mt-5"><button className="primary-btn" data-testid="speech-listen" onClick={() => listening ? recognition.current?.stop() : listen()}>{listening ? 'توقف شنیدن' : 'تبدیل گفتار به متن'} <Mic size={17}/></button><button className="secondary-btn" data-testid="speech-speak" disabled={!text.trim()} onClick={speak}>خواندن متن <Volume2 size={17}/></button><button className="secondary-btn" data-testid="speech-stop" onClick={() => window.speechSynthesis?.cancel()}>توقف صدا</button></div></>; }
function ImageTool({ notify }: { notify: (s: string) => void }) { const [image, setImage] = useState<HTMLImageElement | null>(null); const [brightness, setBrightness] = useState(100); const [contrast, setContrast] = useState(100); const [rotation, setRotation] = useState(0); const [quality, setQuality] = useState(80); const canvas = useRef<HTMLCanvasElement>(null); useEffect(() => { if (!image || !canvas.current) return; const c = canvas.current; const ctx = c.getContext('2d'); if (!ctx) return; const max = 1800; const scale = Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight)); const w = Math.round(image.naturalWidth*scale), h = Math.round(image.naturalHeight*scale); const quarter = rotation % 180 !== 0; c.width = quarter ? h : w; c.height = quarter ? w : h; ctx.filter = `brightness(${brightness}%) contrast(${contrast}%)`; ctx.translate(c.width/2,c.height/2); ctx.rotate(rotation*Math.PI/180); ctx.drawImage(image,-w/2,-h/2,w,h); },[image,brightness,contrast,rotation]); function load(e: ChangeEvent<HTMLInputElement>) { const file = e.target.files?.[0]; if (!file) return; if (file.size > 25*1048576) return notify('تصویر باید کمتر از ۲۵ مگابایت باشد.'); const img = new window.Image(); const url = URL.createObjectURL(file); img.onload = () => { setImage(img); URL.revokeObjectURL(url); }; img.onerror = () => { URL.revokeObjectURL(url); notify('تصویر باز نشد.'); }; img.src = url; } return <><h2>ویرایش و فشرده‌سازی تصویر</h2><p className="muted">ویرایش روی دستگاه انجام می‌شود؛ خروجی JPEG با کیفیت انتخابی ذخیره می‌شود. اندازه تصویر برای عملکرد بهتر حداکثر به ۱۸۰۰ پیکسل می‌رسد.</p><label className="upload-box mt-5"><ImageIcon size={27}/><strong>انتخاب تصویر</strong><input data-testid="image-picker" type="file" accept="image/*" onChange={load}/></label>{image && <><div className="image-preview"><canvas data-testid="image-canvas" ref={canvas}/></div><div className="settings-grid mt-5"><label className="field-label">روشنایی: {brightness}٪<input data-testid="image-brightness" type="range" min="20" max="180" value={brightness} onChange={e => setBrightness(Number(e.target.value))}/></label><label className="field-label">کنتراست: {contrast}٪<input data-testid="image-contrast" type="range" min="20" max="180" value={contrast} onChange={e => setContrast(Number(e.target.value))}/></label><label className="field-label">کیفیت خروجی: {quality}٪<input data-testid="image-quality" type="range" min="20" max="100" value={quality} onChange={e => setQuality(Number(e.target.value))}/></label></div><div className="button-row mt-5"><button className="secondary-btn" data-testid="image-rotate" onClick={() => setRotation((rotation+90)%360)}>چرخش ۹۰ درجه</button><button className="primary-btn" data-testid="image-download" onClick={() => canvas.current?.toBlob(blob => { if (blob) { saveBlob(blob,'habib-edited.jpg'); notify('تصویر در پوشهٔ دانلود ذخیره شد.'); } },'image/jpeg',quality/100)}>ذخیره تصویر <Download size={17}/></button></div></>}</>; }
function VaultTool({ notify }: { notify: (s: string) => void }) { const [passphrase, setPassphrase] = useState(''); const [open, setOpen] = useState(false); const [entries, setEntries] = useState<{ id: string; label: string; secret: string }[]>([]); const [label, setLabel] = useState(''); const [secret, setSecret] = useState(''); const [revealed, setRevealed] = useState<string[]>([]); const [vaultError, setVaultError] = useState(''); async function key(salt: Uint8Array) { const material = await crypto.subtle.importKey('raw', new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']); return crypto.subtle.deriveKey({ name:'PBKDF2',salt: salt as BufferSource,iterations:210000,hash:'SHA-256' },material,{ name:'AES-GCM',length:256 },false,['encrypt','decrypt']); } async function unlock() { setVaultError(''); if (passphrase.length < 8) return setVaultError('گذرواژه باید دست‌کم ۸ نویسه باشد.'); const raw = localStorage.getItem('habib-vault'); if (!raw) { setOpen(true); return; } try { const data = JSON.parse(raw); const salt = Uint8Array.from(atob(data.salt),c => c.charCodeAt(0)); const iv = Uint8Array.from(atob(data.iv),c => c.charCodeAt(0)); const bytes = Uint8Array.from(atob(data.data),c => c.charCodeAt(0)); const decrypted = await crypto.subtle.decrypt({ name:'AES-GCM',iv },await key(salt),bytes); setEntries(JSON.parse(new TextDecoder().decode(decrypted))); setOpen(true); } catch { setVaultError('گذرواژه درست نیست یا اطلاعات صندوق آسیب دیده است.'); } } async function persist(next: typeof entries) { try { const salt = crypto.getRandomValues(new Uint8Array(16)); const iv = crypto.getRandomValues(new Uint8Array(12)); const encrypted = new Uint8Array(await crypto.subtle.encrypt({ name:'AES-GCM',iv },await key(salt),new TextEncoder().encode(JSON.stringify(next)))); const encode = (a: Uint8Array) => btoa(Array.from(a, x => String.fromCharCode(x)).join('')); localStorage.setItem('habib-vault',JSON.stringify({ salt:encode(salt),iv:encode(iv),data:encode(encrypted) })); setEntries(next); notify('اطلاعات صندوق رمزگذاری و ذخیره شد.'); } catch { notify('ذخیره صندوق انجام نشد.'); } } return <><h2>صندوق رمزهای شخصی</h2><p className="muted">رمزها با گذرواژهٔ مخصوص خودتان روی این دستگاه رمزگذاری می‌شوند. اگر گذرواژه را فراموش کنید، بازیابی رمزها ممکن نیست.</p>{!open ? <div className="form-stack mt-5"><label className="field-label">گذرواژه صندوق (حداقل ۸ نویسه)<input data-testid="vault-passphrase" type="password" value={passphrase} onChange={e => setPassphrase(e.target.value)}/></label>{vaultError && <div className="form-error" data-testid="vault-error">{vaultError}</div>}<button data-testid="vault-unlock" className="primary-btn" onClick={unlock}>{localStorage.getItem('habib-vault') ? 'باز کردن صندوق' : 'ساخت صندوق'} <LockKeyhole size={17}/></button></div> : <><div className="button-row mt-5"><button className="secondary-btn" data-testid="vault-lock" onClick={() => { setOpen(false); setEntries([]); setPassphrase(''); setRevealed([]); }}>قفل کردن</button></div><form className="input-action mt-5" onSubmit={e => { e.preventDefault(); if (!label.trim() || !secret.trim()) return notify('عنوان و رمز را وارد کنید.'); persist([{id:uid(),label:label.trim(),secret},...entries]); setLabel(''); setSecret(''); }}><input data-testid="vault-label" placeholder="عنوان حساب" value={label} onChange={e => setLabel(e.target.value)}/><input data-testid="vault-secret" placeholder="رمز" value={secret} onChange={e => setSecret(e.target.value)}/><button className="primary-btn" data-testid="vault-add">ذخیره</button></form><div className="item-list">{entries.map((entry,i) => <div key={entry.id} data-testid={'vault-entry-' + i} className="item-row"><strong>{entry.label}</strong><span dir="ltr" className="secret-value">{revealed.includes(entry.id) ? entry.secret : '••••••••'}</span><button className="secondary-btn" data-testid={'vault-reveal-' + i} onClick={() => setRevealed(revealed.includes(entry.id) ? revealed.filter(x => x !== entry.id) : [...revealed,entry.id])}>{revealed.includes(entry.id) ? 'پنهان' : 'نمایش'}</button><button className="icon-btn danger" data-testid={'vault-delete-' + i} onClick={() => persist(entries.filter(x => x.id !== entry.id))}><Trash2 size={17}/></button></div>)}{!entries.length && <div className="empty">صندوق هنوز خالی است.</div>}</div></>}</>; }
function FlashlightTool({ notify }: { notify: (s: string) => void }) { const [on, setOn] = useState(false); const stream = useRef<MediaStream | null>(null); useEffect(() => () => { stream.current?.getTracks().forEach(t => t.stop()); },[]); async function toggle() { if (on) { stream.current?.getTracks().forEach(t => t.stop()); stream.current = null; setOn(false); return; } try { const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode:'environment' } }); const track = s.getVideoTracks()[0]; const caps = track.getCapabilities() as MediaTrackCapabilities & { torch?: boolean }; if (!caps.torch) { s.getTracks().forEach(t => t.stop()); return notify('چراغ‌قوه از این مرورگر یا دوربین قابل کنترل نیست.'); } await track.applyConstraints({ advanced: [{ torch: true } as MediaTrackConstraintSet] }); stream.current = s; setOn(true); } catch { notify('دسترسی دوربین داده نشد یا چراغ‌قوه در دسترس نیست.'); } } return <div className="center-tool"><div className={'flash-circle ' + (on ? 'flash-on' : '')}><Flashlight size={52}/></div><h2>چراغ‌قوه دوربین</h2><p className="muted">در صورت پشتیبانی گوشی، هنگام روشن‌کردن اجازه دوربین درخواست می‌شود. با خروج از این بخش، چراغ خاموش می‌شود.</p><button className="primary-btn" data-testid="flashlight-toggle" onClick={toggle}>{on ? 'خاموش کردن' : 'روشن کردن چراغ'}</button></div>; }
function CompassTool() { const [heading, setHeading] = useState<number | null>(null); const [error, setError] = useState(''); const [active, setActive] = useState(false); const hasHeading = useRef(false); const handler = useRef<(e: DeviceOrientationEvent) => void>(() => {}); useEffect(() => () => window.removeEventListener('deviceorientation',handler.current),[]); async function start() { try { const orientation = DeviceOrientationEvent as typeof DeviceOrientationEvent & { requestPermission?: () => Promise<string> }; if (orientation.requestPermission && await orientation.requestPermission() !== 'granted') throw Error(); handler.current = e => { const webkit = e as DeviceOrientationEvent & { webkitCompassHeading?: number }; const h = webkit.webkitCompassHeading ?? (e.alpha === null ? null : (360 - e.alpha) % 360); if (h !== null) { hasHeading.current = true; setHeading(Math.round(h)); } }; window.addEventListener('deviceorientation',handler.current); setActive(true); setTimeout(() => { if (!hasHeading.current) setError('دادهٔ جهت‌یابی دریافت نشد؛ حسگر دستگاه ممکن است پشتیبانی نشود.'); }, 3500); } catch { setError('اجازه یا حسگر جهت‌یابی در دسترس نیست.'); } } return <div className="center-tool"><div className="compass-face"><span>شمال</span><Compass size={74} style={{ transform:`rotate(${heading || 0}deg)` }}/><span data-testid="compass-heading">{heading === null ? '—' : `${heading}°`}</span></div><h2>جهت‌یاب تقریبی</h2><p className="muted">مقدار حسگر جهت دستگاه نمایش داده می‌شود و لزوماً شمال واقعی یا قطب‌نمای دقیق نیست. برای اطلاعات قابل اعتماد از قطب‌نمای اختصاصی گوشی استفاده کنید.</p>{error && <p className="form-error">{error}</p>}{!active && <button className="primary-btn" data-testid="compass-start" onClick={start}>شروع جهت‌یابی</button>}</div>; }
function StorageTool({ notes, tasks, notify }: { notes: number; tasks: number; notify: (s: string) => void }) { const [usage, setUsage] = useState<{ usage: number; quota: number } | null>(null); const [error, setError] = useState(''); useEffect(() => { if (!navigator.storage?.estimate) { setError('گزارش حافظه در این دستگاه پشتیبانی نمی‌شود.'); return; } navigator.storage.estimate().then(v => setUsage({ usage:v.usage || 0, quota:v.quota || 0 })).catch(() => setError('اطلاعات حافظه دریافت نشد.')); },[]); return <><h2>حافظه همین برنامه</h2><p className="muted">مرورگر تنها فضای ذخیره‌سازی این برنامه را گزارش می‌کند؛ امکان مشاهده یا پاکسازی همه حافظه گوشی از داخل برنامه وجود ندارد.</p>{usage ? <div className="storage-card"><HardDrive size={30}/><strong data-testid="storage-usage">{bytes(usage.usage)}</strong><span>از حدود {bytes(usage.quota)} فضای مجاز مرورگر استفاده شده</span><div className="progress-track"><div style={{width:`${usage.quota ? Math.min(100,usage.usage/usage.quota*100) : 0}%`}}/></div></div> : <div className="empty">{error || 'در حال دریافت وضعیت حافظه...'}</div>}<div className="button-row mt-5"><span className="pill">{notes} یادداشت</span><span className="pill">{tasks} کار</span></div><p className="help-text mt-5">پاک‌کردن اطلاعات از تنظیمات گوشی یا مرورگر ممکن است یادداشت‌ها و رمزهای ذخیره‌شده را هم حذف کند؛ قبل از آن پشتیبان بگیرید.</p><button className="secondary-btn mt-5" data-testid="storage-refresh" onClick={() => navigator.storage?.estimate().then(v => setUsage({usage:v.usage || 0,quota:v.quota || 0})).catch(() => notify('وضعیت حافظه دریافت نشد.'))}>به‌روزرسانی وضعیت</button></>; }
export default App;
